pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user1, address user2, uint256 amount1, uint256 amount2, uint256 withdrawAmount, bool user1Fails) public {
        vm.assume(user1 != address(0) && user2 != address(0) && user1 != user2);
        vm.assume(user1 != address(c) && user2 != address(c));
        amount1 = bound(amount1, 1, 1 ether);
        amount2 = bound(amount2, 1, 1 ether);
        withdrawAmount = bound(withdrawAmount, 1, 1 ether);

        // Deploy adversarial counterparts: one that may fail, one that always succeeds
        Reverter reverter = new Reverter();
        address normalUser = user2;

        // User1 deposits using the adversarial helper address so its receive can be made to fail
        vm.deal(user1, amount1);
        vm.prank(user1);
        c.deposit{value: amount1}();

        // User2 deposits normally (just EOA, always succeeds)
        vm.deal(user2, amount2);
        vm.prank(user2);
        c.deposit{value: amount2}();

        // Now initiate withdrawAll from user1's address. We route the call through the reverter if user1Fails is true,
        // otherwise we just let user1 withdraw normally. But the bug concerns a failing call to msg.sender.
        // To test that, we must make msg.sender be the adversarial contract during the withdraw.
        // So we need to prank as the reverter contract, which was the msg.sender of the deposit?
        // Wait, credit belongs to msg.sender of deposit. If we deposited from user1, credit is for user1.
        // To trigger the bug, the recipient of the low-level call during withdrawAll must fail.
        // The low-level call goes to msg.sender (the caller of withdrawAll). So the caller must be a contract that fails.
        // So we need an adversarial caller that calls withdrawAll and has its fallback revert.
        // We'll use a helper that, given the choice, calls withdrawAll and optionally reverts in its receive.
        // Simplest: deploy an attacker that, when called with a bool, calls withdrawAll on c.
        // But the fuzzer supplies the bool, we can use it to make the attacker fail on receive or not.
        // Let's design:
        // Attacker has a function attack(address c, bool shouldRevert) payable => it calls C(c).withdrawAll()
        // Its receive() reverts if shouldRevert true, else succeeds.
        // We'll need to fund it with credit first by depositing from attacker.

        // Instead, we can have user1 deposit as normal, then we prank as the adversarial participant.
        // But we need the adversarial participant to have the credit. So we deposit from reverter's address?
        // Let's use a separate setup: deploy attacker, fund attacker with Ether, deposit from attacker,
        // then call attacker.attack(...) which calls withdrawAll, and attacker's receive may revert.
        // That meets the requirement: the fuzzer supplies the decision (shouldRevert), and the attacker is the deployed adversarial helper.

        // Fresh approach:
        // 1. Deploy attacker contract that has a public deposit function (just forwards to c.deposit)
        //    and a public trigger function that calls c.withdrawAll().
        //    Its receive() conditionally reverts based on a bool set before the call.
        // 2. Fund attacker, deposit via attacker (so credit assigned to attacker).
        // 3. Call attacker.trigger(bool fail) -> calls c.withdrawAll, attacker's receive may revert.
        // 4. Assert property.

        Attacker att = new Attacker();
        vm.deal(address(att), amount1);
        att.deposit{value: amount1}(address(c));

        // User2 deposits normally
        vm.deal(user2, amount2);
        vm.prank(user2);
        c.deposit{value: amount2}();

        // Trigger withdrawAll from attacker, with choice of failure
        att.trigger(address(c), user1Fails);

        // After all actions, compute sum of known credits + internal balance and compare to actual ether balance.
        // We know credits for user2 and att. We can query c.credit (mapping is internal, no getter).
        // But we need a public way to read user credits. The contract C has no public getter for credit.
        // We must rely on observable state: balance is public? In original C, 'balance' is uint without visibility -> internal.
        // Actually 'uint balance;' is internal. No public getters exist. So we cannot read internal balance or credit from outside.
        // The only public functions are withdrawAll and deposit, neither returns anything. No view functions.
        // Thus we cannot assert on internal state directly.
        // We can only assert on address(c).balance and perhaps revert behavior.
        // The previous tested approach "internal balance equals ether balance" assumed a balance getter, but there is none.
        // We need a different property observable from the outside.
        // Since the bug leaves internal balance inconsistent, it will manifest when subsequent withdraws are attempted:
        // after a failed withdrawAll, the internal balance is reduced but ether wasn't sent, so the contract might have less internal balance recorded than actual ether.
        // That could cause a later withdrawAll to fail due to insufficient internal balance (underflow or revert in balance -= oCredit).
        // However, the contract does not check balance >= oCredit before subtracting; it will underflow if balance < oCredit (Solidity 0.8.x reverts).
        // So we can observe a revert on a subsequent withdrawAll that should have succeeded.
        // Property: After a potentially failing withdrawAll by a user, another user with credit should still be able to withdrawAll successfully (since ether is still there).
        // The bug may cause the second withdrawAll to revert due to underflow (balance < oCredit) even though ether is sufficient.
        // This is observable: try second withdrawAll and check success.

        // We'll have two users: user2 deposited normally, so they have credit.
        // After the buggy withdrawAll from attacker that fails, attempt withdrawAll from user2 and check it succeeds.
        // In correct version, user2's withdrawAll always succeeds. In buggy, it may revert if internal balance became too low.

        bool user2WithdrawOk;
        vm.prank(user2);
        try c.withdrawAll() { user2WithdrawOk = true; } catch { user2WithdrawOk = false; }

        assertTrue(user2WithdrawOk);
    }
}

contract Attacker {
    bool public fail;
    function deposit(address target) public payable {
        C(target).deposit{value: msg.value}();
    }
    function trigger(address target, bool _fail) public {
        fail = _fail;
        C(target).withdrawAll();
    }
    receive() external payable {
        if (fail) {
            revert("fail");
        }
    }
}

