pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint112 amount1, uint112 amount2, address actor, bool attackCall) public {
        vm.assume(actor != address(0) && actor != address(this) && amount1 > 0 && amount2 > 0);
        uint256 a1 = uint256(amount1);
        uint256 a2 = uint256(amount2);

        // Deposit for two different users to have observable credit
        vm.deal(address(0xAAAA), a1);
        vm.prank(address(0xAAAA));
        c.deposit{value: a1}();

        vm.deal(actor, a2);
        vm.prank(actor);
        c.deposit{value: a2}();

        // Now make actor withdraw via Reverter so the transfer fails.
        Reverter r = new Reverter();
        // Transfer actor's credit to the reverter contract so it can call withdrawAll
        // We need actor to become the reverter; use it as the caller.
        vm.prank(actor);
        // The actor calls withdrawAll; the low-level call goes to actor, but actor is an EOA so succeeds.
        // To trigger the failing call, we need the recipient to revert. So we make the actor
        // call withdrawAll on behalf of the reverter? No, withdrawAll uses msg.sender.
        // Instead, we deposit as reverter and then make reverter call withdrawAll.
        // But reverter has a fallback that reverts, so the low-level call to it will revert.
        // So we need to set up the credit for the Reverter address.
        // Let's deposit for the Reverter.
        vm.deal(address(r), a2);
        vm.prank(address(r));
        c.deposit{value: a2}();

        // Now the reverter calls withdrawAll. The low-level call will be to itself, reverting.
        bool ok;
        vm.prank(address(r));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // After the failed withdrawAll, the invariant: contract's balance >= sum of all credit.
        // For the reference contract, the credit of the Reverter is restored, so its credit remains a2.
        // For the mutant, credit was cleared, so credit is 0 but balance unchanged (no transfer),
        // thus balance < sum(credit) if there is any other creditor.
        // But we also need another creditor to observe the difference: address(0xAAAA).
        // We can compute sum of credit via public getter? "credit" is private mapping, no getter.
        // So we cannot read credit directly. We must use another approach.
        // Instead, use address(this).balance of c (contract's ETH balance) and compare with
        // what we expect. But we cannot sum credit.
        // Alternative: use a public view that returns sum? No.
        // We can observe difference by balance alone? The reference contract after revert:
        // balance unchanged (since balance -= oCredit was not executed). The mutant:
        // credit[reverter] = 0, but balance unchanged (because call reverted after balance -= oCredit?). Wait, in mutant: credit=0; balance -= oCredit; call reverts; but balance was already reduced. So balance is lower, but the ETH wasn't sent. So contract's ETH balance is higher than balance (since no ETH moved). So contract's ETH balance != balance. In reference, contract's ETH balance == balance always?
        // In C, balance is private uint, no getter. So cannot read.
        // How to observe the difference? We can withdraw the other user's funds later and check if balance inconsistent.
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

